<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed,nextTick,watch} from 'vue'
import {Plus,Users,Upload,Download,ArrowLeft,MessageCircle,MoreHorizontal,Search,SlidersHorizontal} from 'lucide-vue-next'
import {useRouter,useRoute,onBeforeRouteLeave} from 'vue-router'
import {useLocal} from '../stores/local'
import AssetLinks from '../media/AssetLinks.vue'
import CharacterPortrait from '../presentation/CharacterPortrait.vue'
import ActionMenu from '../presentation/ActionMenu.vue'
import {useAssetIndex} from '../media/asset-index'
import {composeMedia} from '../media/compose'
import PromotionPanel from '../companion/PromotionPanel.vue'
import type {PromotionTarget} from '../companion/promotion'
import type {Document} from '../domain/local-contract'
import {emptyCard,writeCard,type CharacterCard} from './card-format'
import {parseCardContainer,importCardFile,exportCardFile,cardAvatar} from './card-container'
import type {ChatSession,ChatMessage} from './chat-contract'
import {personaForCards} from './persona'
import CardCollectionPanel from './CardCollectionPanel.vue'
import CardHistoryPanel from './CardHistoryPanel.vue'
import {cardLibrary,saveCardTemplate} from './card-operations'
import {cardDraftValue,cardDraftKey,saveCardDraft,resumeCardDraft,cardFieldNames,type CardDraft} from './card-drafts'
import {canonical} from '../domain/local-contract'
useAssetIndex()
const mediaLifecycle=new AbortController()
const store=useLocal(),cards=ref<Document<CharacterCard>[]>([]),editing=ref<CharacterCard|null>(null),editingId=ref(''),revision=ref(0),error=ref(''),busy=ref(false),loaded=ref(false)
const router=useRouter(),route=useRoute(),sessions=ref<Document<ChatSession>[]>([]),selected=ref<string[]>([])
const promotionTarget=ref<PromotionTarget|null>(null)
const selecting=ref(false),importOpen=ref(false)
const search=ref(''),avatars=ref<Record<string,string>>({}),preview=ref<{file:File;name:string;format:string;assets:number;warnings:string[]}[]>([]),importFailures=ref<string[]>([]),notice=ref(''),fullData=ref('')
const tagFilter=ref(''),groupFilter=ref(''),showArchived=ref(false),collectionRows=ref<Document<CharacterCard>[]|null>(null),historyId=ref<string|null>(null),drafts=ref<Document<CardDraft>[]>([]),draftStatus=ref(''),fieldReview=ref(false),editorLoading=ref(false)
const tags=computed(()=>[...new Set(cards.value.flatMap(row=>row.value.tags))].sort()),groups=computed(()=>[...new Set(cards.value.flatMap(row=>cardLibrary(row.value).groups))].sort())
const visibleCards=computed(()=>cards.value.filter(row=>route.query.card===row.id||cardLibrary(row.value).archived===showArchived.value&&(row.value.name+' '+row.value.tags.join(' ')).toLowerCase().includes(search.value.toLowerCase())&&(!tagFilter.value||row.value.tags.includes(tagFilter.value))&&(!groupFilter.value||cardLibrary(row.value).groups.includes(groupFilter.value))))
let editorEpoch=0,draftPending=0,draftWork=Promise.resolve(),durableEditor='',editorSlot:DraftSlot|null=null
const draftController=new AbortController()
type DraftSlot={id:string;revision:number;createdAt:string;conflict:boolean;conflictId:string;row:Document<CardDraft>|null}
function editorSignature(){return editing.value?canonical({id:editingId.value,revision:revision.value,fields:Object.fromEntries(cardFieldNames.map(field=>[field,editing.value![field]])),dataText:fullData.value,review:fieldReview.value}):''}
async function loadDrafts(){const vault=store.vault;if(!vault)return;const rows=await vault.list<CardDraft>('settings');if(disposed||store.vault!==vault||!vault.unlocked)return;drafts.value=rows.filter(row=>row.value.assetType==='card-editor-draft'&&!row.value.retired).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
async function persistEditorDraft(){const vault=store.vault,slot=editorSlot;if(!vault||!editing.value||!slot||editorLoading.value||disposed)return;const signature=editorSignature();const token=editorEpoch,value={...cardDraftValue(editingId.value,revision.value,editing.value,fullData.value),createdAt:slot.createdAt,conflict:slot.conflict,requiresFieldReview:fieldReview.value};draftStatus.value='正在保存草稿…';draftPending++;const work=draftWork.catch(()=>{}).then(async()=>{if(!vault.unlocked||draftController.signal.aborted)return;if(token===editorEpoch&&signature===durableEditor){if(!disposed&&store.vault===vault&&editorSignature()===signature)draftStatus.value=slot.conflict?'另一份草稿已保存':'草稿已保存';return}let next:Document<CardDraft>;try{next=await saveCardDraft(vault,slot.id,slot.revision,{...value,conflict:slot.conflict},draftController.signal)}catch(e){if((e as {code?:string}).code!=='REVISION_CONFLICT')throw e;slot.id=slot.conflictId;slot.revision=slot.row?.id===slot.id?slot.row.revision:0;slot.conflict=true;next=await saveCardDraft(vault,slot.id,slot.revision,{...value,conflict:true},draftController.signal)}slot.revision=next.revision;slot.row=next;if(!disposed&&token===editorEpoch&&store.vault===vault){durableEditor=signature;draftStatus.value=editorSignature()===signature?(slot.conflict?'另一份草稿已保存':'草稿已保存'):'正在保存草稿…'}}).catch(e=>{if(!disposed&&token===editorEpoch){draftStatus.value='草稿尚未保存';error.value=(e as Error).message}}).finally(()=>{draftPending--});draftWork=work;await work}
watch([editing,fullData,fieldReview],()=>{if(!editorLoading.value)void persistEditorDraft()},{deep:true,flush:'sync'})
async function closeEditor(){if(busy.value||editorLoading.value||disposed)return;const token=editorEpoch,vault=store.vault;await persistEditorDraft();await draftWork;if(disposed||token!==editorEpoch||store.vault!==vault)return;if(editorSignature()!==durableEditor){error.value='草稿尚未保存，请保留这段内容后再离开';return}editorEpoch++;editing.value=null;fullData.value='';editorSlot=null;await loadDrafts()}
async function continueDraft(row:Document<CardDraft>){const vault=store.vault;if(!vault||disposed||busy.value||editorLoading.value)return;if(editing.value){await persistEditorDraft();if(editorSignature()!==durableEditor)return}editorLoading.value=true;const token=++editorEpoch;try{const restored=await resumeCardDraft(vault,row);if(disposed||token!==editorEpoch||store.vault!==vault)return;editingId.value=row.value.cardId;revision.value=restored.cardRevision;editing.value=restored.card;fullData.value=restored.dataText;fieldReview.value=restored.requiresFieldReview;editorSlot={id:row.id,revision:row.revision,createdAt:row.value.createdAt,conflict:row.value.conflict,conflictId:'card-draft-conflict:'+row.value.cardId+':'+crypto.randomUUID(),row};durableEditor=editorSignature();draftStatus.value=row.value.conflict?'另一份草稿已保存':'草稿已保存';error.value=''}catch(e){if(!disposed&&token===editorEpoch)error.value=(e as Error).message}finally{if(token===editorEpoch)editorLoading.value=false}}
async function discardDraft(row:Document<CardDraft>){if(!store.vault)return;try{await saveCardDraft(store.vault,row.id,row.revision,{...row.value,retired:true});await loadDrafts()}catch(e){error.value=(e as Error).message}}
async function rebaseDraft(){
 const vault=store.vault;if(!vault||!editing.value||busy.value||editorLoading.value||disposed)return
 const token=editorEpoch;busy.value=true;try{
  await persistEditorDraft();await draftWork;if(disposed||token!==editorEpoch||store.vault!==vault||!vault.unlocked||editorSignature()!==durableEditor)return
  const cardId=editingId.value,baseRevision=revision.value,current=await vault.read<CharacterCard>(cardId),old=baseRevision?await vault.read<CharacterCard>(cardId,baseRevision):null
  if(disposed||token!==editorEpoch||store.vault!==vault||!vault.unlocked||!editing.value)return
  if(!current||current.kind!=='card'||current.value.identityId!==editing.value.identityId)throw new Error('当前版本不属于这份草稿')
  const fields=Object.fromEntries(cardFieldNames.map(field=>[field,JSON.parse(JSON.stringify(editing.value![field]))]));editorLoading.value=true
  editing.value={...JSON.parse(JSON.stringify(current.value)),...fields};if(old&&fullData.value===JSON.stringify(old.value.data,null,2))fullData.value=JSON.stringify(current.value.data,null,2);else fieldReview.value=true
  revision.value=current.revision;editorLoading.value=false;await persistEditorDraft()
 }catch(e){if(!disposed&&token===editorEpoch&&store.vault===vault)error.value=(e as Error).message}finally{if(token===editorEpoch)editorLoading.value=false;busy.value=false}
}
async function openHistory(id:string){if(busy.value||editorLoading.value||disposed)return;const token=editorEpoch,vault=store.vault;if(editing.value){await persistEditorDraft();await draftWork;if(editorSignature()!==durableEditor)return}if(!disposed&&token===editorEpoch&&store.vault===vault)historyId.value=id}
async function historyRestored(){historyId.value=null;editorEpoch++;editing.value=null;fullData.value='';editorSlot=null;await load();await loadDrafts()}
async function collectionChanged(){selected.value=[];await load();await loadDrafts()}

let disposed=false,controller=new AbortController(),avatarController=new AbortController()
async function load(){const vault=store.vault;if(!vault)return;const [nextCards,nextSessions]=await Promise.all([vault.list<CharacterCard>('card'),vault.list<ChatSession>('session')]);if(disposed||store.vault!==vault)return;cards.value=nextCards.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)||a.value.name.localeCompare(b.value.name));await loadDrafts();if(disposed||store.vault!==vault||!vault.unlocked)return;sessions.value=nextSessions.filter(row=>!row.value.archived&&!row.value.companionId).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));avatarController.abort();avatarController=new AbortController();const signal=avatarController.signal;for(const url of Object.values(avatars.value))URL.revokeObjectURL(url);avatars.value={};void (async()=>{for(const row of nextCards){if(signal.aborted||disposed)break;try{const url=await cardAvatar(vault,row,signal);if(url){if(signal.aborted||disposed||store.vault!==vault)URL.revokeObjectURL(url);else avatars.value[row.id]=url}}catch{/* A missing image never removes a readable character card. */}}})()}
async function openChat(members:Document<CharacterCard>[]){const vault=store.vault;if(!vault||busy.value)return;if(members.length!==1&&(members.length<3||members.length>8)){error.value='群聊请选择 3—8 位角色';return}busy.value=true;try{const persona=await personaForCards(vault,members);const id=crypto.randomUUID(),at=new Date().toISOString(),messageIds:string[]=[],writes=[];for(const card of members){if(card.value.firstMessage){const messageId=crypto.randomUUID(),variantId=crypto.randomUUID(),message:ChatMessage={sessionId:id,role:'assistant',speakerId:card.value.identityId,variants:[{id:variantId,text:card.value.firstMessage,taskId:null,state:'complete',createdAt:at}],selectedVariantId:variantId,hidden:false,createdAt:at};messageIds.push(messageId);writes.push({kind:'message' as const,id:messageId,expectedRevision:0,value:message})}}const chat:ChatSession={title:members.map(row=>row.value.name).join(' · '),cards:members.map(row=>({id:row.id,revision:row.revision,value:row.value})),messageIds,persona:persona?{name:persona.value.name,description:persona.value.description}:{name:'读者',description:''},mode:'reader',authorNote:'',modelOverride:null,archived:false,parent:null,createdAt:at,currentTaskId:null};await vault.commitBundle(crypto.randomUUID(),[{kind:'session',id,expectedRevision:0,value:chat},...writes],controller.signal);if(disposed||store.vault!==vault||!vault.unlocked)return;await router.push('/local/chat/'+id)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function portrait(row:Document<CharacterCard>){const vault=store.vault;if(!vault)return;try{const destination=await composeMedia(vault,{signal:mediaLifecycle.signal,prompt:row.value.description+'\n'+row.value.personality,source:{targetId:row.id,targetKind:'card',targetRevision:row.revision,role:'portrait'}});if(!disposed&&store.vault===vault&&vault.unlocked)await router.push(destination)}catch(e){if(!disposed)error.value=(e as Error).message}}
async function edit(row?:Document<CharacterCard>){if(busy.value||editorLoading.value||disposed)return;if(editing.value){await persistEditorDraft();if(editorSignature()!==durableEditor)return}const vault=store.vault;if(!vault)return;editorLoading.value=true;const token=++editorEpoch;editing.value=row?JSON.parse(JSON.stringify(row.value)):emptyCard();editingId.value=row?.id||crypto.randomUUID();revision.value=row?.revision||0;fullData.value=JSON.stringify(editing.value!.data,null,2);fieldReview.value=false;error.value='';draftStatus.value='';const id=cardDraftKey(editingId.value);try{const saved=await vault.read<CardDraft>(id);if(disposed||token!==editorEpoch||store.vault!==vault)return;if(saved&&saved.value.assetType==='card-editor-draft'&&!saved.value.retired){const restored=await resumeCardDraft(vault,saved);if(disposed||token!==editorEpoch)return;editing.value=restored.card;revision.value=restored.cardRevision;fullData.value=restored.dataText;fieldReview.value=restored.requiresFieldReview;draftStatus.value='草稿已保存'}editorSlot={id,revision:saved?.revision||0,createdAt:saved?.value.createdAt||new Date().toISOString(),conflict:false,conflictId:'card-draft-conflict:'+editingId.value+':'+crypto.randomUUID(),row:saved&&!saved.value.retired?saved:null};if(saved?.value.retired){editorSlot.id='card-draft-conflict:'+editingId.value+':'+crypto.randomUUID();editorSlot.revision=0;editorSlot.createdAt=new Date().toISOString();editorSlot.conflict=true;editorSlot.row=null}durableEditor=editorSignature()}catch(e){if(!disposed&&token===editorEpoch){error.value=(e as Error).message;durableEditor='';editorSlot=null}}finally{if(token===editorEpoch)editorLoading.value=false}}
async function save(){const vault=store.vault;if(!vault||!editing.value||disposed||busy.value||editorLoading.value)return;if(!editing.value.name.trim()){error.value='请填写角色名字';return}if(fieldReview.value){error.value='请先检查迁移后的完整字段草稿';return}busy.value=true;const token=editorEpoch;try{await persistEditorDraft();await draftWork;if(editorSignature()!==durableEditor)throw new Error('草稿尚未保存，请稍后重试');const data=JSON.parse(fullData.value);if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('完整字段需要是 JSON 对象');if(data.tags!==undefined&&(!Array.isArray(data.tags)||data.tags.some((tag:unknown)=>typeof tag!=='string')))throw new Error('标签需要是字符串数组');const card:CharacterCard={...JSON.parse(JSON.stringify(editing.value)),name:editing.value.name.trim(),data,tags:data.tags===undefined?[...editing.value.tags]:data.tags};writeCard(card);await saveCardTemplate(vault,editingId.value,revision.value,card,crypto.randomUUID(),controller.signal,editorSlot?.row||undefined);if(disposed||token!==editorEpoch||store.vault!==vault||!vault.unlocked)return;editorEpoch++;editing.value=null;fullData.value='';editorSlot=null;durableEditor='';await load();if(!disposed&&(route.query.create==='1'||typeof route.query.draft==='string'))await router.replace({path:route.path,query:{...route.query,create:undefined,draft:undefined}})}catch(e){if(!disposed&&token===editorEpoch)error.value=(e as Error).message}finally{busy.value=false}}

async function upload(event:Event){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);busy.value=true;error.value='';preview.value=[];importFailures.value=[];controller.abort();controller=new AbortController();const signal=controller.signal;try{if(files.length>64)throw new Error('一次最多预览 64 张角色卡');for(const file of files){signal.throwIfAborted();try{if(file.size>100*1024*1024)throw new Error('角色包超过 100 MiB');const format=file.name.toLowerCase().endsWith('.charx')?'charx':file.name.toLowerCase().endsWith('.png')?'png':'json',parsed=await parseCardContainer(new Uint8Array(await file.arrayBuffer()),format,signal);if(disposed)return;preview.value.push({file,name:parsed.card.name,format:parsed.card.format,assets:parsed.entries.size,warnings:parsed.warnings})}catch(e){if(signal.aborted)throw e;importFailures.value.push(file.name+'：'+(e as Error).message)}}}catch(e){if(!disposed)error.value=signal.aborted?'预览已停止':(e as Error).message}finally{busy.value=false;input.value=''}}
async function confirmImport(){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';notice.value='';let saved=0;try{for(const item of [...preview.value]){controller.signal.throwIfAborted();try{await importCardFile(vault,item.file,controller.signal);saved++;preview.value=preview.value.filter(row=>row!==item)}catch(e){if(controller.signal.aborted)throw e;importFailures.value.push(item.file.name+'：'+(e as Error).message)}}await load();notice.value='已导入 '+saved+' 张角色卡'}catch(e){if(!disposed)error.value=controller.signal.aborted?'导入已停止，已保存的卡仍保留':(e as Error).message}finally{busy.value=false}}
function cancelImport(){controller.abort();controller=new AbortController();preview.value=[];importFailures.value=[]}
async function download(card:CharacterCard,format:'json'|'png'|'charx'='json'){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';try{const bytes=await exportCardFile(vault,card,format,controller.signal);if(disposed||store.vault!==vault||!vault.unlocked||controller.signal.aborted)return;const url=URL.createObjectURL(new Blob([Uint8Array.from(bytes)],{type:format==='json'?'application/json':format==='png'?'image/png':'application/zip'})),link=document.createElement('a');link.href=url;link.download=card.name+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function locateCard(){const id=route.query.card;if(typeof id!=='string')return;await nextTick();const node=document.getElementById('card-'+id);node?.scrollIntoView({block:'center'});node?.focus({preventScroll:true})}
watch(()=>route.query.card,()=>void locateCard())
function beforeUnload(event:BeforeUnloadEvent){if(editing.value&&(draftPending>0||editorSignature()!==durableEditor)){event.preventDefault();event.returnValue=''}}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);void load().then(async()=>{loaded.value=true;if(typeof route.query.draft==='string'){const row=await store.vault?.read<CardDraft>(route.query.draft);if(!row||row.kind!=='settings'||row.value.assetType!=='card-editor-draft')throw new Error('这份角色草稿已不可用');await continueDraft(row)}else if(route.query.create==='1'){const vault=store.vault;if(!vault)return;const id=crypto.randomUUID(),card=emptyCard(),row=await saveCardDraft(vault,cardDraftKey(id),0,cardDraftValue(id,0,card,JSON.stringify(card.data,null,2)),draftController.signal);if(!disposed&&store.vault===vault&&vault.unlocked)await router.replace({path:route.path,query:{...route.query,create:undefined,draft:row.id}})}else await locateCard()}).catch(e=>{if(!disposed){error.value=(e as Error).message;loaded.value=true}})})
onBeforeRouteLeave(async()=>{await persistEditorDraft();await draftWork;if(editing.value&&editorSignature()!==durableEditor){error.value='草稿尚未保存，请保留内容后再离开';return false}})
onUnmounted(()=>{window.removeEventListener('beforeunload',beforeUnload);draftController.abort();editorEpoch++;mediaLifecycle.abort();disposed=true;editing.value=null;fullData.value='';controller.abort();avatarController.abort();for(const url of Object.values(avatars.value))URL.revokeObjectURL(url)})
</script>
<template>
<section class="character-library">
  <div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">CHARACTERS</span><h1>{{editing?editing.name:'角色'}}</h1></div><div class="final-page-actions"><button v-if="!editing" class="final-icon-button" aria-label="导入角色卡" :aria-pressed="importOpen" @click="importOpen=!importOpen"><Upload :size="19"/></button><button v-if="!editing&&cards.length" :aria-pressed="selecting" @click="selecting=!selecting;if(!selecting)selected=[]">{{selecting?'取消':'选择'}}</button><button v-if="editing" @click="closeEditor"><ArrowLeft :size="17"/>返回</button><button v-else class="final-primary final-icon-button" aria-label="创建角色" @click="edit()"><Plus :size="20"/></button></div></div>
  <p v-if="error" class="final-error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
  <form v-if="editing" class="final-card-form" @submit.prevent="save"><fieldset class="card-editor-fields" :disabled="busy||editorLoading"><p v-if="draftStatus" class="final-subtle" role="status">{{draftStatus}}</p><p v-if="cards.some(row=>row.id===editingId&&row.revision!==revision)" class="final-error">库卡已有新修订。<button type="button" @click="rebaseDraft">以当前版本保存这份草稿</button></p><p v-if="fieldReview" class="final-error">完整字段草稿需要确认。<button type="button" @click="fieldReview=false">我已检查字段</button><button type="button" @click="fullData=JSON.stringify(editing.data,null,2);fieldReview=false">使用已恢复的字段</button></p>
    <label>姓名<input v-model="editing.name" required maxlength="200"></label>
    <label>人物简介<textarea v-model="editing.description" maxlength="30000"></textarea></label>
    <label>性格与说话习惯<textarea v-model="editing.personality" maxlength="20000"></textarea></label>
    <label>故事背景<textarea v-model="editing.scenario" maxlength="20000"></textarea></label>
    <label>开场白<textarea v-model="editing.firstMessage" maxlength="30000"></textarea></label>
    <details><summary>更多角色设定</summary><label>对话示例<textarea v-model="editing.exampleMessages"></textarea></label><label>作者说明<textarea v-model="editing.creatorNotes"></textarea></label><label>系统提示<textarea v-model="editing.systemPrompt"></textarea></label><label>末尾提示<textarea v-model="editing.postHistoryInstructions"></textarea></label>
      <fieldset><legend>备用开场</legend><label v-for="(_greeting,index) in editing.alternateGreetings" :key="index">开场 {{index+1}}<textarea v-model="editing.alternateGreetings[index]"></textarea><button type="button" @click="editing.alternateGreetings.splice(index,1)">移除</button></label><button type="button" @click="editing.alternateGreetings.push('')">添加开场</button></fieldset>
      <label>世界书、资源与完整扩展<textarea v-model="fullData" class="final-code-input" spellcheck="false" rows="12"></textarea></label>
    </details>
    <button v-if="revision" type="button" @click="openHistory(editingId)">修订记录</button><button class="final-primary" :disabled="busy||editorLoading">{{busy?'正在保存…':'保存角色'}}</button></fieldset>
  </form>
  <template v-else><details v-if="drafts.length" class="final-card-drafts"><summary>待续编辑 · {{drafts.length}}</summary><div v-for="row in drafts" :key="row.id"><button @click="continueDraft(row)">{{row.value.fields.name||'未命名角色'}} · {{row.value.conflict?'另一份草稿':'草稿'}}</button><button @click="discardDraft(row)">结束这份草稿</button></div></details>
    <details class="character-tools"><summary><SlidersHorizontal :size="17"/>酒馆工具</summary><div class="final-page-actions"><RouterLink class="final-text-link" to="/local/agent/skills?operation=card-design">AI 建卡</RouterLink><RouterLink to="/local/lorebooks" class="final-text-link">世界书</RouterLink><RouterLink to="/local/tavern/quick-replies" class="final-text-link">快捷按钮</RouterLink><RouterLink to="/local/tavern/presets" class="final-text-link">提示预设</RouterLink><RouterLink to="/local/tavern/regex" class="final-text-link">正则</RouterLink><RouterLink to="/local/tavern/personas" class="final-text-link">我的身份</RouterLink><RouterLink to="/local/tavern/import-chat" class="final-text-link">导入对话</RouterLink></div></details>
    <label v-if="importOpen" class="final-import-panel"><span><Upload :size="18"/> 导入角色卡</span><input type="file" accept=".json,.png,.charx" multiple :disabled="busy" @change="upload"><small class="final-subtle">JSON · PNG · CHARX / V1—V3</small></label>
    <section v-if="preview.length||importFailures.length" class="final-import-panel" aria-label="角色卡导入预览"><h2>导入预览</h2><article v-for="item in preview" :key="item.file.name+item.file.size" class="final-card-import-row"><strong>{{item.name}}</strong><span class="final-subtle">{{item.format.toUpperCase()}} · {{item.file.name}} · {{item.assets}} 个包内文件</span><p v-for="warning in item.warnings" :key="warning" class="final-subtle">{{warning}}</p></article><p v-for="failure in importFailures" :key="failure" class="final-error">{{failure}}</p><div class="final-grid-actions"><button class="final-primary" :disabled="busy||!preview.length" @click="confirmImport">导入 {{preview.length}} 张</button><button :disabled="busy" @click="cancelImport">取消</button><button v-if="busy" @click="controller.abort()">停止</button></div></section>
