    <button v-if="selected.length" @click="collectionRows=cards.filter(row=>selected.includes(row.id))">整理 {{selected.length}} 张角色</button><button v-if="selected.length>=3&&selected.length<=8" class="final-primary" :disabled="busy" @click="openChat(cards.filter(row=>selected.includes(row.id)))">与所选 {{selected.length}} 位角色建群</button>
    <section v-if="sessions.length"><div class="final-section-title"><h2>最近的对话</h2></div><div class="final-collection-grid"><RouterLink v-for="chat in sessions" :key="chat.id" :to="'/local/chat/'+chat.id" class="final-character-card"><h2>{{chat.value.title}}</h2><span class="final-subtle">{{chat.value.messageIds.length}} 条消息</span></RouterLink></div></section>
  </template>
<CardCollectionPanel v-if="collectionRows" :rows="collectionRows" @close="collectionRows=null" @changed="collectionChanged"/><CardHistoryPanel v-if="historyId" :card-id="historyId" @close="historyId=null" @restored="historyRestored"/><PromotionPanel v-if="promotionTarget" :target="promotionTarget" @close="promotionTarget=null"/>
</section>
</template>

